const v = input || {};

function pick(key) {
  const raw = v[key];
  if (raw === undefined || raw === null || String(raw).trim() === "") {
    return `[MISSING: ${key}]`;
  }
  return String(raw).trim();
}

function escapePdfText(value) {
  return String(value || "")
    .replace(/\/g, "\\")
    .replace(/\(/g, "\(")
    .replace(/\)/g, "\)")
    .replace(//g, " ")
    .replace(/
/g, " ");
}

function makePdfBase64(text) {
  const lines = String(text || "").split(/?
/).slice(0, 220);
  const stream = ["BT", "/F1 11 Tf", "50 790 Td"];
  for (let i = 0; i < lines.length; i += 1) {
    const line = escapePdfText(lines[i]).slice(0, 120);
    stream.push(`(${line}) Tj`);
    if (i < lines.length - 1) {
      stream.push("0 -14 Td");
    }
  }
  stream.push("ET");
  const content = stream.join("\n");

  const objects = [
    null,
    "1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n",
    "2 0 obj\n<< /Type /Pages /Kids [3 0 R] /Count 1 >>\nendobj\n",
    "3 0 obj\n<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>\nendobj\n",
    "4 0 obj\n<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>\nendobj\n",
    `5 0 obj\n<< /Length ${Buffer.byteLength(content, "utf8")} >>\nstream\n${content}\nendstream\nendobj\n`
  ];

  let pdf = "%PDF-1.4\n";
  const offsets = [0];
  for (let i = 1; i < objects.length; i += 1) {
    offsets[i] = Buffer.byteLength(pdf, "utf8");
    pdf += objects[i];
  }

  const xrefOffset = Buffer.byteLength(pdf, "utf8");
  pdf += "xref\n0 6\n0000000000 65535 f \n";
  for (let i = 1; i < offsets.length; i += 1) {
    pdf += `${String(offsets[i]).padStart(10, "0")} 00000 n \n`;
  }
  pdf += `trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n${xrefOffset}\n%%EOF`;
  return Buffer.from(pdf, "utf8").toString("base64");
}

const agreement = [
  "SERVICE AGREEMENT",
  "",
  `This Service Agreement ("Agreement") is made between ${pick("provider_name")} ("Provider") and ${pick("client_name")} ("Client").`,
  "",
  "1) Services",
  `Provider will deliver the following services: ${pick("service_name")}.`,
  "",
  "2) Term",
  `Start Date: ${pick("start_date")}`,
  `End Date: ${pick("end_date")}`,
  "",
  "3) Fees and Payment",
  `Client agrees to pay ${pick("currency")} ${pick("fee_amount")}.`,
  `Payment Terms: ${pick("payment_terms")}.`,
  "",
  "4) Confidentiality",
  "Both parties agree to keep confidential information private and use it only for this engagement.",
  "",
  "5) Governing Law",
  `This Agreement is governed by the laws of ${pick("jurisdiction")}.`,
  "",
  "6) Special Terms",
  `${pick("special_terms")}`,
  "",
  "7) Signatures",
  `Provider: ${pick("provider_name")}`,
  `Client: ${pick("client_name")}`,
  `Client Email: ${pick("client_email")}`
].join("\n");

const agreementTitle = `Agreement - ${pick("client_name")}`;
const fileName = `${agreementTitle.replace(/[^a-zA-Z0-9_-]+/g, "_")}.pdf`;
const agreementPdfBase64 = makePdfBase64(agreement);

return {
  agreement_text: agreement,
  agreement_title: agreementTitle,
  agreement_file_name: fileName,
  agreement_pdf_base64: agreementPdfBase64,
  generated_at: new Date().toISOString()
};
